#!/usr/bin/env python3
import os
import re
import sys
from pathlib import Path
from datetime import datetime
import pytesseract
from PIL import Image
import pandas as pd
from openpyxl import load_workbook

DATASET_ROOT = Path('/app/workspace/dataset')
OUTPUT_PATH = Path('/app/workspace/fuel_packets.xlsx')

IMAGE_EXTS = {'.png', '.jpg', '.jpeg', '.tif', '.tiff', '.bmp', '.gif', '.webp'}

def collect_image_paths():
    images = []
    for root, _, files in os.walk(DATASET_ROOT):
        for f in files:
            p = Path(root) / f
            if p.suffix.lower() in IMAGE_EXTS:
                rel = p.relative_to(DATASET_ROOT).as_posix()
                batch = rel.split('/')[0] if '/' in rel else rel
                images.append({'abs_path': p, 'relative_path': rel, 'batch_name': batch})
    return images

def ocr_image(image_path):
    try:
        img = Image.open(image_path)
        return pytesseract.image_to_string(img)
    except Exception as e:
        print(f'OCR failed for {image_path}: {e}', file=sys.stderr)
        return ''

def is_fuel_receipt(text):
    txt = text.lower()
    return any(k in txt for k in ['fuel receipt', 'pump sale', 'tax invoice'])

def extract_txn_ref(text):
    # Look for patterns like 'Txn Ref: ABC123' or 'Transaction No ABC123' etc.
    lines = text.splitlines()
    for i, line in enumerate(lines):
        low = line.lower()
        if any(label in low for label in ['txn ref', 'transaction no', 'ref no']):
            # try same line after colon or after label
            m = re.search(r'[:\-]\s*([A-Z0-9]+)', line, re.IGNORECASE)
            if m:
                return m.group(1).strip()
            # try after space
            parts = line.split()
            if len(parts) >= 2:
                candidate = parts[-1]
                if re.fullmatch(r'[A-Z0-9]+', candidate):
                    return candidate.strip()
            # try next line
            if i + 1 < len(lines):
                nxt = lines[i+1].strip()
                if re.fullmatch(r'[A-Z0-9]+', nxt):
                    return nxt
    return ''

def parse_date_string(ds):
    # Attempt formats in order, returning ISO string or empty.
    for fmt in ['%d/%m/%Y', '%d-%m-%Y', '%m/%d/%Y', '%Y-%m-%d']:
        try:
            dt = datetime.strptime(ds, fmt)
            # when ambiguous (both day and month <=12) we already prioritize DD/MM/Y above MM/DD/Y.
            return dt.strftime('%Y-%m-%d')
        except Exception:
            continue
    return ''

def extract_date(text):
    lines = text.splitlines()
    for i, line in enumerate(lines):
        low = line.lower()
        if 'sale date' in low or 'date' == low.strip() or low.startswith('date'):
            # try to find a date token on the same line
            m = re.search(r'(\d{2}[/-]\d{2}[/-]\d{4}|\d{4}[/-]\d{2}[/-]\d{2})', line)
            if m:
                iso = parse_date_string(m.group(1))
                if iso:
                    return iso
            # else look at next line
            if i + 1 < len(lines):
                nxt = lines[i+1]
                m = re.search(r'(\d{2}[/-]\d{2}[/-]\d{4}|\d{4}[/-]\d{2}[/-]\d{2})', nxt)
                if m:
                    iso = parse_date_string(m.group(1))
                    if iso:
                        return iso
    return ''

def extract_total_amount(text):
    # Prepare lines without discount/tax etc.
    lines = text.splitlines()
    candidates = []
    for idx, line in enumerate(lines):
        low = line.lower()
        # skip if any ignore keyword present
        if any(kw in low for kw in ['discount', 'cashback', 'savings', 'loyalty', 'tax']):
            continue
        # check for keywords
        kw_priority = None
        if 'grand total' in low:
            kw_priority = 1
        elif 'total amount' in low:
            kw_priority = 2
        elif 'amount paid' in low:
            kw_priority = 3
        elif re.search(r'\btotal\b', low):
            kw_priority = 4
        if kw_priority is not None:
            # try to find number on same line
            m = re.search(r'([\d,]+\.\d{2})', line)
            if m:
                candidates.append((kw_priority, m.group(1)))
                continue
            # else next line
            if idx + 1 < len(lines):
                nxt = lines[idx+1]
                m = re.search(r'([\d,]+\.\d{2})', nxt)
                if m:
                    candidates.append((kw_priority, m.group(1)))
    if not candidates:
        return ''
    # pick lowest priority number (most specific)
    candidates.sort(key=lambda x: x[0])
    raw = candidates[0][1]
    # clean commas and $ sign
    clean = raw.replace(',', '').replace('$', '')
    try:
        val = float(clean)
        return f"{val:.2f}"
    except Exception:
        return ''

def process_images(images):
    rows = []
    for img in images:
        txt = ocr_image(img['abs_path'])
        if not txt:
            continue
        if not is_fuel_receipt(txt):
            print(f"Skipping non-receipt: {img['relative_path']}")
            continue
        txn = extract_txn_ref(txt)
        date = extract_date(txt)
        total = extract_total_amount(txt)
        rows.append({
            'batch_name': img['batch_name'],
            'relative_path': img['relative_path'],
            'txn_ref': txn,
            'date': date,
            'total_amount': total,
        })
        print(f"Processed {img['relative_path']}: txn={txn} date={date} total={total}")
    return rows

def deduplicate(rows):
    seen = set()
    out = []
    for row in rows:
        ref = row['txn_ref']
        if ref and ref in seen:
            continue
        if ref:
            seen.add(ref)
        out.append(row)
    return out

def write_excel(rows):
    df = pd.DataFrame(rows, columns=['batch_name', 'relative_path', 'txn_ref', 'date', 'total_amount'])
    df.sort_values('relative_path', inplace=True)
    # Ensure total_amount stays as string
    df['total_amount'] = df['total_amount'].astype(str)
    # Write with openpyxl engine
    with pd.ExcelWriter(OUTPUT_PATH, engine='openpyxl') as writer:
        df.to_excel(writer, index=False, sheet_name='transactions')
    print(f"Excel written to {OUTPUT_PATH}")

def validate_excel():
    if not OUTPUT_PATH.exists():
        print('Validation failed: output file does not exist.', file=sys.stderr)
        return
    wb = load_workbook(OUTPUT_PATH, data_only=True)
    if 'transactions' not in wb.sheetnames:
        print('Validation failed: sheet name is not transactions', file=sys.stderr)
        return
    ws = wb['transactions']
    headers = [cell.value for cell in next(ws.iter_rows(min_row=1, max_row=1))]
    expected = ['batch_name', 'relative_path', 'txn_ref', 'date', 'total_amount']
    if headers != expected:
        print(f'Validation failed: headers {headers} != {expected}', file=sys.stderr)
    rows = list(ws.iter_rows(min_row=2, values_only=True))
    # Check sorting
    rel_paths = [r[1] for r in rows]
    if rel_paths != sorted(rel_paths):
        print('Validation warning: rows not sorted by relative_path', file=sys.stderr)
    txn_refs = [r[2] for r in rows if r[2]]
    if len(txn_refs) != len(set(txn_refs)):
        print('Validation warning: duplicate txn_ref values found', file=sys.stderr)
    # Check each row fields
    empty_issues = []
    date_pat = re.compile(r'\d{4}-\d{2}-\d{2}')
    amount_pat = re.compile(r'\d+\.\d{2}')
    for idx, r in enumerate(rows, start=2):
        batch, rel, txn, date, total = r
        if not txn or not date or not total:
            empty_issues.append(idx)
        if date and not date_pat.fullmatch(str(date)):
            print(f'Row {idx} date format invalid: {date}', file=sys.stderr)
        if total and not amount_pat.fullmatch(str(total)):
            print(f'Row {idx} total_amount format invalid: {total}', file=sys.stderr)
    if empty_issues:
        print(f'Validation warning: rows with empty fields at lines {empty_issues}', file=sys.stderr)
    print(f'Total rows: {len(rows)}')
    for r in rows[:5]:
        print(r)

def main():
    images = collect_image_paths()
    rows = process_images(images)
    rows = deduplicate(rows)
    write_excel(rows)
    validate_excel()

if __name__ == '__main__':
    main()

